catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
	if (isLoading || newValue == '') {
		return;
	}
	g_form.getReference('identity', function (user) {
		if (user) {
			g_form.showFieldMsg('identity', 'Validating user ' + user.name + ' exists in SailPoint... Please Wait', 'info');
			g_form.setDisabled('identity', true);
			var filter = 'email eq "' + user.email + '"';

			var ga_identity = new GlideAjax('XalientGlideAjaxHelper');
			ga_identity.addParam('sysparm_name', 'getIdentity');
			ga_identity.addParam('sysparm_filter', filter);
			ga_identity.getXMLAnswer(function (response) {
				var identity_response = JSON.parse(response);
				g_form.hideFieldMsg('identity');
				if (identity_response.length == 0) {
					g_form.showFieldMsg('identity', 'Unable to find a record for ' + user.name + ' in SailPoint. Please choose another user', 'error');
					g_form.clearValue('identity_id');
				}
				else {
					g_form.hideFieldMsg('identity');
					g_form.setValue('identity_id',identity_response[0].id);
				}

			});
			g_form.setDisabled('identity', false);
		}
	});
}
